import{_ as p,a0 as o,w as l,s as h,I as s,x as t,a1 as i,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Linux 平台下 Python 脚本编程入门（一） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 平台下 Python 脚本编程入门（一） | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 平台下 Python 脚本编程入门（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 平台下 Python 脚本编程入门（一） | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160525 Getting Started with Python Programming and Scripting in Linux – Part 1","title":"Linux 平台下 Python 脚本编程入门（一）","tag":"201608","desc":""},"relativePath":"201608/20160525 Getting Started with Python Programming and Scripting in Linux – Part 1.md","filePath":"[post].md"}'),r={name:"201608/20160525 Getting Started with Python Programming and Scripting in Linux – Part 1.md"};function g(u,n,c,y,m,k){const a=o("Link");return l(),h("div",null,[n[21]||(n[21]=s("h1",{id:"linux-平台下-python-脚本编程入门-一",tabindex:"-1"},[t("Linux 平台下 Python 脚本编程入门（一） "),s("a",{class:"header-anchor",href:"#linux-平台下-python-脚本编程入门-一","aria-label":"Permalink to “Linux 平台下 Python 脚本编程入门（一）”"},"​")],-1)),n[22]||(n[22]=s("p",null,"众所周知，系统管理员需要精通一门脚本语言，而且招聘机构列出的职位需求上也会这么写。大多数人会认为 Bash （或者其他的 shell 语言）用起来很方便，但一些强大的语言（比如 Python）会给你带来一些其它的好处。",-1)),n[23]||(n[23]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/05/Learn-Python-Programming-Scripting-in-Linux.png",alt:""})],-1)),n[24]||(n[24]=s("p",null,[s("em",null,"在 Linux 中学习 Python 脚本编程")],-1)),n[25]||(n[25]=s("p",null,"首先，我们会使用 Python 的命令行工具，还会接触到 Python 的面向对象特性（这篇文章的后半部分会谈到它）。",-1)),s("p",null,[n[2]||(n[2]=t("学习 Python 可以助力于你在",-1)),i(a,{href:"http://www.tecmint.com/create-gui-applications-in-linux/"},{default:e(()=>[...n[0]||(n[0]=[t("桌面应用开发",-1)])]),_:1}),n[3]||(n[3]=t("及",-1)),i(a,{href:"http://www.datasciencecentral.com/profiles/blogs/the-guide-to-learning-python-for-data-science-2"},{default:e(()=>[...n[1]||(n[1]=[t("数据科学领域",-1)])]),_:1}),n[4]||(n[4]=t("的职业发展。",-1))]),n[26]||(n[26]=d(`<p>容易上手，广泛使用，拥有海量“开箱即用”的模块（它是一组包含 Python 语句的外部文件），Python 理所当然地成为了美国计算机专业大学生在一年级时所上的程序设计课所用语言的不二之选。</p><p>在这个由两篇文章构成的系列中，我们将回顾 Python 的基础部分，希望初学编程的你能够将这篇实用的文章作为一个编程入门的跳板，和日后使用 Python 时的一篇快速指引。</p><h3 id="linux-中的-python" tabindex="-1">Linux 中的 Python <a class="header-anchor" href="#linux-中的-python" aria-label="Permalink to “Linux 中的 Python”">​</a></h3><p>Python 2.x 和 3.x 通常已经内置在现代 Linux 发行版中，你可以立刻使用它。你可以终端模拟器中输入 <code>python</code> 或 <code>python3</code> 来进入 Python shell, 并输入 <code>quit()</code> 退出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which python</span></span>
<span class="line"><span>$ which python3</span></span>
<span class="line"><span>$ python -v</span></span>
<span class="line"><span>$ python3 -v</span></span>
<span class="line"><span>$ python</span></span>
<span class="line"><span>&gt;&gt;&gt; quit()</span></span>
<span class="line"><span>$ python3</span></span>
<span class="line"><span>&gt;&gt;&gt; quit()</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Running-Python-Commands-on-Linux.png" alt=""></p><p><em>在 Linux 中运行 Python 命令</em></p><p>如果你希望在键入 <code>python</code> 时使用 Python 3.x 而不是 2.x，你可以像下面一样更改对应的符号链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm /usr/bin/python </span></span>
<span class="line"><span>$ cd /usr/bin</span></span>
<span class="line"><span>$ ln -s python3.2 python # Choose the Python 3.x binary here</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Remove-Python-2-and-Use-Python-3.png" alt=""></p><p><em>删除 Python 2，使用 Python 3</em></p><p>顺便一提，有一点需要注意：尽管 Python 2.x 仍旧被使用，但它并不会被积极维护。因此，你可能要考虑像上面指示的那样来切换到 3.x。2.x 和 3.x 的语法有一些不同，我们会在这个系列文章中使用后者。</p><p>另一个在 Linux 中使用 Python 的方法是通过 IDLE (the Python Integrated Development Environment)，这是一个为编写 Python 代码而生的图形用户界面。在安装它之前，你最好查看一下适用于你的 Linux 发行版的 IDLE 可用版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># aptitude search idle     [Debian 及其衍生发行版]</span></span>
<span class="line"><span># yum search idle          [CentOS 和 Fedora]</span></span>
<span class="line"><span># dnf search idle          [Fedora 23+ 版本]</span></span></code></pre></div><p>然后，你可以像下面一样安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo aptitude install idle-python3.2    # I&#39;m using Linux Mint 13</span></span></code></pre></div><p>安装成功后，你会看到 IDLE 的运行画面。它很像 Python shell，但是你可以用它做更多 Python shell 做不了的事。</p><p>比如，你可以:</p><ol><li><p>轻松打开外部文件 (File → Open)；</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Python-Shell.png" alt=""></p><p><em>Python Shell</em></p></li><li><p>复制 (<code>Ctrl + C</code>) 和粘贴 (<code>Ctrl + V</code>) 文本；</p></li><li><p>查找和替换文本；</p></li><li><p>显示可能的代码补全（一个在其他 IDE 里可能叫做“智能感知”或者“自动补完”的功能）；</p></li><li><p>更改字体和字号，等等。</p></li></ol><p>最厉害的是，你可以用 IDLE 创建桌面应用。</p><p>我们在这两篇文章中不会开发桌面应用，所以你可以根据喜好来选择 IDLE 或 Python shell 去运行下面的例子。</p><h3 id="python-中的基本运算" tabindex="-1">Python 中的基本运算 <a class="header-anchor" href="#python-中的基本运算" aria-label="Permalink to “Python 中的基本运算”">​</a></h3><p>就像你预料的那样，你能够直接进行算术操作（你可以在你的所有运算中使用足够多的括号！），还可以轻松地使用 Python 拼接字符串。</p><p>你还可以将运算结果赋给一个变量，然后在屏幕上显示它。Python 有一个叫做拼接 (concatenation) 的实用功能——给 print 函数提供一串用逗号分隔的变量和/或字符串，它会返回一个由你刚才提供的变量依序构成的句子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; a = 5</span></span>
<span class="line"><span>&gt;&gt;&gt; b = 8</span></span>
<span class="line"><span>&gt;&gt;&gt; x = b / a</span></span>
<span class="line"><span>&gt;&gt;&gt; x</span></span>
<span class="line"><span>1.6</span></span>
<span class="line"><span>&gt;&gt;&gt; print(b, &quot;divided by&quot;, a, &quot;equals&quot;, x)</span></span></code></pre></div><p>注意，你可以将不同类型的变量（数字，字符串，布尔符号等等）混合在一起。当你将一个值赋给一个变量后，你可以随后更改它的类型，不会有任何问题（因此，Python 被称为动态类型语言）。</p><p>如果你尝试在静态类型语言中（如 Java 或 C#）做这件事，它将抛出一个错误。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Learn-Python-Basic-Operations.png" alt=""></p><p><em>学习 Python 的基本操作</em></p><h3 id="面向对象编程的简单介绍" tabindex="-1">面向对象编程的简单介绍 <a class="header-anchor" href="#面向对象编程的简单介绍" aria-label="Permalink to “面向对象编程的简单介绍”">​</a></h3><p>在面向对象编程（OOP）中，程序中的所有实体都会由对象的形式呈现，并且它们可以与其他对象交互。因此，对象拥有属性，而且大多数对象可以执行动作（这被称为对象的方法）。</p><p>举个例子：我们来想象一下，创建一个对象“狗”。它可能拥有的一些属性有<code>颜色</code>、<code>品种</code>、<code>年龄</code>等等，而它可以完成的动作有 <code>叫()</code>、<code>吃()</code>、<code>睡觉()</code>，诸如此类。</p><p>你可以看到，方法名后面会跟着一对括号，括号当中可能会包含一个或多个参数（向方法中传递的值），也有可能什么都不包含。</p><p>我们用 Python 的基本对象类型之一——列表来解释这些概念。</p><h3 id="解释对象的属性和方法-python-中的列表" tabindex="-1">解释对象的属性和方法：Python 中的列表 <a class="header-anchor" href="#解释对象的属性和方法-python-中的列表" aria-label="Permalink to “解释对象的属性和方法：Python 中的列表”">​</a></h3><p>列表是条目的有序组合，而这些条目所属的数据类型并不需要相同。我们像下面一样来使用一对方括号，来创建一个名叫 <code>rockBands</code> 的列表：</p><p>你可以向 <code>rockBands</code> 的 <code>append()</code> 方法传递条目，来将它添加到列表的尾部，就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands = []</span></span>
<span class="line"><span>&gt;&gt;&gt; rockBands.append(&quot;The Beatles&quot;)</span></span>
<span class="line"><span>&gt;&gt;&gt; rockBands.append(&quot;Pink Floyd&quot;)</span></span>
<span class="line"><span>&gt;&gt;&gt; rockBands.append(&quot;The Rolling Stones&quot;)</span></span></code></pre></div><p>为了从列表中移除元素，我们可以向 <code>remove()</code> 方法传递特定元素，或向 <code>pop()</code> 中传递列表中待删除元素的位置（从 0 开始计数）。</p><p>换句话说，我们可以用下面这种方法来从列表中删除 “The Beatles”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands.remove(&quot;The Beatles&quot;)</span></span></code></pre></div><p>或者用这种方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands.pop(0)</span></span></code></pre></div><p>如果你输入了对象的名字，然后在后面输入了一个点，你可以按 <code>Ctrl + space</code> 来显示这个对象的可用方法列表。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/List-Available-Python-Methods.png" alt=""></p><p><em>列出可用的 Python 方法</em></p><p>列表中含有的元素个数是它的一个属性。它通常被叫做“长度”，你可以通过向内建函数 <code>len</code> 传递一个列表作为它的参数来显示该列表的长度（顺便一提，之前的例子中提到的 print 语句，是 Python 的另一个内建函数）。</p><p>如果你在 IDLE 中输入 <code>len</code>，然后跟上一个不闭合的括号，你会看到这个函数的默认语法：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Python-len-Function.png" alt=""></p><p><em>Python 的 len 函数</em></p><p>现在我们来看看列表中的特定条目。它们也有属性和方法吗？答案是肯定的。比如，你可以将一个字符串条目转换为大写形式，并获取这个字符串所包含的字符数量。像下面这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands[0].upper()</span></span>
<span class="line"><span>&#39;THE BEATLES&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; len(rockBands[0])</span></span>
<span class="line"><span>11</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在这篇文章中，我们简要介绍了 Python、它的命令行 shell、IDLE，展示了如何执行算术运算，如何在变量中存储数据，如何使用 <code>print</code> 函数在屏幕上重新显示那些数据（无论是它们本身还是它们的一部分），还通过一个实际的例子解释了对象的属性和方法。</p><p>下一篇文章中，我们会展示如何使用条件语句和循环语句来实现流程控制。我们也会解释如何编写一个脚本来帮助我们完成系统管理任务。</p>`,55)),s("p",null,[n[6]||(n[6]=t("你是不是想继续学习一些有关 Python 的知识呢？敬请期待本系列的第二部分（我们会在脚本中将 Python 和命令行工具的优点结合在一起），你还可以考虑购买我们的《终极 Python 编程》系列教程（",-1)),i(a,{href:"http://www.tecmint.com/learn-python-programming-online-with-ultimate-python-coding/"},{default:e(()=>[...n[5]||(n[5]=[t("这里",-1)])]),_:1}),n[7]||(n[7]=t("有详细信息）。",-1))]),n[27]||(n[27]=s("p",null,"像往常一样，如果你对这篇文章有什么问题，可以向我们寻求帮助。你可以使用下面的联系表单向我们发送留言，我们会尽快回复你。",-1)),n[28]||(n[28]=s("hr",null,null,-1)),s("p",null,[n[9]||(n[9]=t("via: ",-1)),i(a,{href:"http://www.tecmint.com/learn-python-programming-and-scripting-in-linux/"},{default:e(()=>[...n[8]||(n[8]=[t("http://www.tecmint.com/learn-python-programming-and-scripting-in-linux/",-1)])]),_:1})]),s("p",null,[n[13]||(n[13]=t("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:e(()=>[...n[10]||(n[10]=[t("Gabriel Cánepa",-1)])]),_:1}),n[14]||(n[14]=t(" 译者：",-1)),i(a,{href:"https://github.com/StdioA"},{default:e(()=>[...n[11]||(n[11]=[t("StdioA",-1)])]),_:1}),n[15]||(n[15]=t(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[12]||(n[12]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[18]||(n[18]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[16]||(n[16]=[t("LCTT",-1)])]),_:1}),n[19]||(n[19]=t(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...n[17]||(n[17]=[t("Linux中国",-1)])]),_:1}),n[20]||(n[20]=t(" 荣誉推出",-1))])])}const f=p(r,[["render",g]]);export{x as __pageData,f as default};
